const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const main=document.querySelector('#main');
function updateNoteCount(){const s=store.get();const n=(s.savedResources||[]).length+(s.savedSupports||[]).length+(s.completed||[]).length;document.querySelector('#note-count').textContent=n}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function pageHero(eyebrow,title,desc){return `<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="/">홈</a> / ${esc(title)}</div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="section-desc">${desc}</p></div></section>`}
function stageStrip(active){return `<div class="roadmap-strip">${stages.map((s,i)=>`<a class="roadmap-step ${active===s.slug?'active':''}" href="/roadmap/${s.slug}/"><span>${i+1}</span>${s.name}</a>`).join('')}</div>`}
