function stageGuideMode(slug){if(['before-start','validation','registration'].includes(slug))return'samantha';if(['first-sales','operations','growth'].includes(slug))return'monica';return'duo'}
function guidePicture(character='samantha',variant='guide',className=''){const c=guideCharacters[character];const avatar=variant==='avatar';const base=`/assets/${c.asset}/${c.asset}-${avatar?'avatar':'guide'}`;return `<picture class="guide-picture guide-${c.tone} ${className}"><source type="image/avif" srcset="${base}.avif"><source type="image/webp" srcset="${base}.webp"><img src="${avatar?`${base}.png`:`/assets/${c.asset}/original/${c.asset}-guide.png`}" width="${avatar?256:c.width}" height="${avatar?256:c.height}" loading="${avatar?'lazy':'eager'}" decoding="async" alt=""></picture>`}
function guideBlock(mode,message='',{messages={},action='',href='',compact=false,variant='avatar'}={}){const keys=mode==='duo'?['samantha','monica']:[mode];return `<aside class="guide-callout guide-mode-${mode} ${compact?'guide-callout-compact':''}" aria-label="${mode==='duo'?'사만다와 모니카의 창업 안내':guideCharacters[mode].role}"><div class="guide-people">${keys.map(key=>{const c=guideCharacters[key],copy=messages[key]||message;return `<div class="guide-person guide-person-${c.tone}">${guidePicture(key,variant,'guide-callout-picture')}<div class="guide-copy"><span class="guide-label">${c.role}</span><p>${copy}</p></div></div>`}).join('')}</div>${action&&href?`<a class="text-link guide-action" href="${href}">${action} →</a>`:''}</aside>`}
function duoWelcome(){return `<section class="section-sm duo-welcome"><div class="container"><div class="duo-welcome-head"><div class="eyebrow">두 명의 창업 길잡이</div><h2 class="section-title">준비부터 실행까지, 사만다와 모니카가 함께 안내해 드려요.</h2></div>${guideBlock('duo','',{messages:{samantha:'어디서 시작할지 막막하다면, 지금 상황부터 정리해 볼까요?',monica:'고른 단계에서 바로 활용할 자료와 실행 순서를 안내해 드릴게요.'},action:'7단계 로드맵 보기',href:'/roadmap/',variant:'guide'})}</div></section>`}
